INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4038925, 578660, 70100, '<td valign="top">Good colors. Great detail in the rocks</td>', 'Good colors. Great detail in the rocks', '2007-08-29 15:17:50.000000', NULL, 1),
(4038929, 578631, 70100, '<td valign="top">Good idea but way too much blown sky.  Try -2/3 EV or so next time.</td>', 'Good idea but way too much blown sky.  Try -2/3 EV or so next time.', '2007-08-29 15:19:18.000000', NULL, 1),
(4038930, 578646, 70100, '<td valign="top">Now THAT''S dangerous</td>', 'Now THAT''S dangerous', '2007-08-29 15:19:41.000000', NULL, 1),
(4038935, 578556, 70100, '<td valign="top">Great action but needs to be lightened up to get the detail.  Possibly use a curves filter to assign the black point??</td>', 'Great action but needs to be lightened up to get the detail.  Possibly use a curves filter to assign the black point??', '2007-08-29 15:20:56.000000', NULL, 1),
(4038939, 577906, 42100, '<td valign="top">Always risky business messing with any kind of stimulates...point well made.  Your arrangement of items is a little on the busy side and doesn''t draw the eye to the primary subject cleanly.</td>', 'Always risky business messing with any kind of stimulates...point well made.  Your arrangement of items is a little on the busy side and doesn''t draw the eye to the primary subject cleanly.', '2007-08-29 15:21:34.000000', NULL, 1),
(4038946, 578109, 70100, '<td valign="top">LMAO --  Now that''s without a net.</td>', 'LMAO --  Now that''s without a net.', '2007-08-29 15:23:23.000000', NULL, 1),
(4038951, 578124, 70100, '<td valign="top">Good action</td>', 'Good action', '2007-08-29 15:24:35.000000', NULL, 1),
(4038953, 578171, 70100, '<td valign="top">You might want to try some HDR technique here. The dynamic range is pretty wide.  Solid image even as is tho.</td>', 'You might want to try some HDR technique here. The dynamic range is pretty wide.  Solid image even as is tho.', '2007-08-29 15:25:54.000000', NULL, 1),
(4038955, 578394, 42100, '<td valign="top">Different interpretation of the challenge, really showing a comparison of old and new technology.  The shadows and light from the window are neat, but they are confusing an already very busy composition.</td>', 'Different interpretation of the challenge, really showing a comparison of old and new technology.  The shadows and light from the window are neat, but they are confusing an already very busy composition.', '2007-08-29 15:26:37.000000', NULL, 1),
(4038959, 577640, 70100, '<td valign="top">Good shot.  Might suggest bumping the contrast just a bit to give a sharper effect.</td>', 'Good shot.  Might suggest bumping the contrast just a bit to give a sharper effect.', '2007-08-29 15:27:33.000000', NULL, 1),
(4038964, 578039, 70100, '<td valign="top">Really can''t see the subject well against the trees. There''s no real focal point here.</td>', 'Really can''t see the subject well against the trees. There''s no real focal point here.', '2007-08-29 15:29:11.000000', NULL, 1),
(4038968, 578548, 70100, '<td valign="top">At least the message is clear. LOL</td>', 'At least the message is clear. LOL', '2007-08-29 15:30:10.000000', NULL, 1),
(4038972, 577868, 70100, '<td valign="top">Thank god for blue pants. Seriously good colors.</td>', 'Thank god for blue pants. Seriously good colors.', '2007-08-29 15:30:49.000000', NULL, 1),
(4038973, 578636, 42100, '<td valign="top">A very interesting tree and the boy poses well to help sell the point.  The tree is very busy though and the boy almost disappears into the limbs.  One less limb crossing in front of him might help.</td>', 'A very interesting tree and the boy poses well to help sell the point.  The tree is very busy though and the boy almost disappears into the limbs.  One less limb crossing in front of him might help.', '2007-08-29 15:32:10.000000', NULL, 1),
(4038978, 577947, 70100, '<td valign="top">Nice job.  Perhaps crop tighter on the bug right at the right edge of the plant??</td>', 'Nice job.  Perhaps crop tighter on the bug right at the right edge of the plant??', '2007-08-29 15:32:54.000000', NULL, 1),
(4038995, 576695, 42100, '<td valign="top">The tones are very nice and a great capture of action.  Compositions where the subject is leaving the frame offer an interesting tension.  But here he is so close to the edge of the frame that the balance really feels off.</td>', 'The tones are very nice and a great capture of action.  Compositions where the subject is leaving the frame offer an interesting tension.  But here he is so close to the edge of the frame that the balance really feels off.', '2007-08-29 15:36:41.000000', NULL, 1),
(4039003, 578655, 70100, '<td valign="top">Dangerous angle (LOL).</td>', 'Dangerous angle (LOL).', '2007-08-29 15:38:42.000000', NULL, 1),
(4039011, 578145, 70100, '<td valign="top">Great colors but the silouhette really doesn''t add that much here.</td>', 'Great colors but the silouhette really doesn''t add that much here.', '2007-08-29 15:40:31.000000', NULL, 1),
(4039016, 578248, 70100, '<td valign="top">Great lighting, great pose, gorgeous girl.  The whole thing works and hits a 10 for me.</td>', 'Great lighting, great pose, gorgeous girl.  The whole thing works and hits a 10 for me.', '2007-08-29 15:42:35.000000', NULL, 1),
(4039017, 577960, 70100, '<td valign="top">Great composition.  Great DOF. Great idea. and funny with it. Absolute 10!</td>', 'Great composition.  Great DOF. Great idea. and funny with it. Absolute 10!', '2007-08-29 15:42:40.000000', NULL, 1),
(4039018, 577955, 70100, '<td valign="top">Great Noir mood, good lighting.  Very Bogart!</td>', 'Great Noir mood, good lighting.  Very Bogart!', '2007-08-29 15:42:45.000000', NULL, 1),
(4039030, 578612, 42100, '<td valign="top">Since the sky is already blown out, a little more detail in the shadowed areas of the workers faces would be nice.  This would make for an interesting high-key study.</td>', 'Since the sky is already blown out, a little more detail in the shadowed areas of the workers faces would be nice.  This would make for an interesting high-key study.', '2007-08-29 15:45:20.000000', NULL, 1),
(4039039, 578249, 42100, '<td valign="top">Ouch...a real heart breaker.  An intimate moment seems like it might be deserving of a little more intimate composition...a little too much going on in this composition.</td>', 'Ouch...a real heart breaker.  An intimate moment seems like it might be deserving of a little more intimate composition...a little too much going on in this composition.', '2007-08-29 15:47:39.000000', NULL, 1),
(4039043, 578613, 9668, '<td valign="top">Top 10. Great shot.</td>', 'Top 10. Great shot.', '2007-08-29 15:49:37.000000', NULL, 1),
(4039054, 578469, 9668, '<td valign="top">Amazing. Great image you''ve captured here. The DOF is awesome with the skater in focus and the crowd only slightly out of focus. And to have that sharp of detail, and to get his facial expression at the decisive moment. Awesome.</td>', 'Amazing. Great image you''ve captured here. The DOF is awesome with the skater in focus and the crowd only slightly out of focus. And to have that sharp of detail, and to get his facial expression at the decisive moment. Awesome.', '2007-08-29 15:51:41.000000', NULL, 1),
(4039073, 578248, 30049, '<td valign="top">This is a lovely provocative shot of a model.  Nicely done.  That being said, without describing the connection to the challenge in your title I don''t see how this fits.  JMO of course.  :)</td>', 'This is a lovely provocative shot of a model.  Nicely done.  That being said, without describing the connection to the challenge in your title I don''t see how this fits.  JMO of course.  :)', '2007-08-29 15:59:21.000000', NULL, 1),
