(4040995, 578492, 14437, '<td valign="top">I don''t see what''s the risk from what she''s doing.</td>', 'I don''t see what''s the risk from what she''s doing.', '2007-08-30 06:09:22.000000', NULL, 1),
(4040997, 577563, 14437, '<td valign="top">A color production of this photo could be better. Besides, what''s the risk?</td>', 'A color production of this photo could be better. Besides, what''s the risk?', '2007-08-30 06:11:11.000000', NULL, 1),
