(4041348, 578406, 81664, '<td valign="top">Great job, a little too sharpened perhaps though.</td>', 'Great job, a little too sharpened perhaps though.', '2007-08-30 11:11:41.000000', NULL, 1),
(4041351, 578675, 76198, '<td valign="top">I''d like this better in portrait orientation - the gondola looks like it''s hanging sideways; a little confusing to the eye.</td>', 'I''d like this better in portrait orientation - the gondola looks like it''s hanging sideways; a little confusing to the eye.', '2007-08-30 11:12:31.000000', NULL, 1),
(4041352, 577155, 78303, '<td valign="top">You may have done more than basic editing here.  I like the shot as an action shot - good capture and positioning.</td>', 'You may have done more than basic editing here.  I like the shot as an action shot - good capture and positioning.', '2007-08-30 11:12:34.000000', NULL, 1),
(4041353, 578608, 81664, '<td valign="top">oh how cute, very clever. I love his long tail! An excellent shot!</td>', 'oh how cute, very clever. I love his long tail! An excellent shot!', '2007-08-30 11:12:46.000000', NULL, 1),
(4041354, 577960, 81664, '<td valign="top">wow, very clever! I love the concept. Great focus on the rat, and I love the cat''s expression! I give you an 8!</td>', 'wow, very clever! I love the concept. Great focus on the rat, and I love the cat''s expression! I give you an 8!', '2007-08-30 11:13:39.000000', NULL, 1),
(4041356, 578027, 81664, '<td valign="top">Ooh, he is brave! Great action shot too!</td>', 'Ooh, he is brave! Great action shot too!', '2007-08-30 11:15:02.000000', NULL, 1),
(4041357, 578608, 76198, '<td valign="top">Cute. Focus is soft; light is a touch harsh.</td>', 'Cute. Focus is soft; light is a touch harsh.', '2007-08-30 11:15:17.000000', NULL, 1),
(4041358, 577831, 76198, '<td valign="top">That''s just nuts. Nice capture.</td>', 'That''s just nuts. Nice capture.', '2007-08-30 11:15:56.000000', NULL, 1),
