INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4041364, 577539, 76198, '<td valign="top">That''s awesome.</td>', 'That''s awesome.', '2007-08-30 11:17:34.000000', NULL, 1),
(4041368, 578469, 81664, '<td valign="top">Neat shot, I love the little kid''s expression (w/ blue shirt) and the kid next to him with his head covered. I suppose that could distract from the true subject, but I like the shot!</td>', 'Neat shot, I love the little kid''s expression (w/ blue shirt) and the kid next to him with his head covered. I suppose that could distract from the true subject, but I like the shot!', '2007-08-30 11:19:15.000000', NULL, 1),
(4041369, 577339, 76198, '<td valign="top">I suspect that this is not a DPC friendly shot, but it''s a beauty nonetheless; great color; beautiful light. Very expressive. Not sure the title helps it.</td>', 'I suspect that this is not a DPC friendly shot, but it''s a beauty nonetheless; great color; beautiful light. Very expressive. Not sure the title helps it.', '2007-08-30 11:19:17.000000', NULL, 1),
(4041376, 576965, 76198, '<td valign="top">Pretty shot, though very much a shoehorn. I wish both poles stayed within the frame.</td>', 'Pretty shot, though very much a shoehorn. I wish both poles stayed within the frame.', '2007-08-30 11:21:13.000000', NULL, 1),
(4041383, 578568, 81664, '<td valign="top">Really good concept, but a little dark.</td>', 'Really good concept, but a little dark.', '2007-08-30 11:22:09.000000', NULL, 1),
(4041385, 576669, 76198, '<td valign="top">Beauty. Perhaps the best yet. Perfect DOF, great contrast, great sense of movement.</td>', 'Beauty. Perhaps the best yet. Perfect DOF, great contrast, great sense of movement.', '2007-08-30 11:22:18.000000', NULL, 1),
(4041386, 578516, 81664, '<td valign="top">Wow, cool idea. Love the color/lighting too!</td>', 'Wow, cool idea. Love the color/lighting too!', '2007-08-30 11:22:52.000000', NULL, 1),
