(4042543, 576365, 77196, '<td valign="top">Oh you literalist you... Actually this is a nice shot - I''m not thrilled with blurry foregrounds, but you have a nice reflection, nice lighting, and weren''t afraid to go close.</td>', 'Oh you literalist you... Actually this is a nice shot - I''m not thrilled with blurry foregrounds, but you have a nice reflection, nice lighting, and weren''t afraid to go close.', '2007-08-30 21:07:35.000000', NULL, 1),
(4042546, 578171, 33672, '<td valign="top">Great photo for the theme. Great tones and interesting subject.  God bless our troops.</td>', 'Great photo for the theme. Great tones and interesting subject.  God bless our troops.', '2007-08-30 21:10:06.000000', NULL, 1),
(4042550, 578248, 33672, '<td valign="top">Great photo. Beautiful model, Superb lighting.. A bit of a stretch for the theme.</td>', 'Great photo. Beautiful model, Superb lighting.. A bit of a stretch for the theme.', '2007-08-30 21:12:04.000000', NULL, 1),
(4042583, 577957, 48697, '<td valign="top">lol, nice</td>', 'lol, nice', '2007-08-30 21:27:28.000000', NULL, 1),
(4042622, 578171, 48697, '<td valign="top">I really like this shot! First it''s a beatiful shot with great colors and composition. More inportantly is how well this fits in the challenge! I can''t think of a better way of expressing the true meaning of the challenge than you did w/ this shot! Men and Women in the armed services defintly work w/o a net everyday.  Well done!</td>', 'I really like this shot! First it''s a beatiful shot with great colors and composition. More inportantly is how well this fits in the challenge! I can''t think of a better way of expressing the true meaning of the challenge than you did w/ this shot! Men and Women in the armed services defintly work w/o a net everyday.  Well done!', '2007-08-30 21:54:44.000000', NULL, 1),
(4042623, 577539, 48697, '<td valign="top">What a great shot! That''s one crazy skateboard trick.  The b&amp;w is very well done and I love the composition.  What makes this shot, imo, is the fire in his hands, you captured it so well. Well Done!</td>', 'What a great shot! That''s one crazy skateboard trick.  The b&w is very well done and I love the composition.  What makes this shot, imo, is the fire in his hands, you captured it so well. Well Done!', '2007-08-30 21:54:51.000000', NULL, 1),
(4042627, 577088, 48697, '<td valign="top">I love the lighting and the centered composition.  This is a very creative perspective on the challenge and well executed. Well done!</td>', 'I love the lighting and the centered composition.  This is a very creative perspective on the challenge and well executed. Well done!', '2007-08-30 21:55:52.000000', NULL, 1),
(4042628, 578631, 48697, '<td valign="top">nice shot and I love the placement of the soldiers. I feel the the crop is a bit tight on the helicopter. good job.</td>', 'nice shot and I love the placement of the soldiers. I feel the the crop is a bit tight on the helicopter. good job.', '2007-08-30 21:56:00.000000', NULL, 1),
