(4049741, 578248, 44765, '<td valign="top">This is great,Wonderful idea;)</td>', 'This is great,Wonderful idea;)', '2007-09-02 10:06:07.000000', NULL, 1),
(4049759, 578556, 34041, '<td valign="top">If you have PS, tweaking the "shadow / highlight" adjustment might have helped brighten up this image. I find the faces too dark. Greta action shot, however, great focus and stop action.  6 from me.</td>', 'If you have PS, tweaking the "shadow / highlight" adjustment might have helped brighten up this image. I find the faces too dark. Greta action shot, however, great focus and stop action.  6 from me.', '2007-09-02 10:16:39.000000', NULL, 1),
(4049760, 577569, 34041, '<td valign="top">Wish they were facing this way, but otherwise a great shot.  I hope you were far away, with a lonnng lens. 6 from me.</td>', 'Wish they were facing this way, but otherwise a great shot.  I hope you were far away, with a lonnng lens. 6 from me.', '2007-09-02 10:17:45.000000', NULL, 1),
(4049763, 578608, 34041, '<td valign="top">Cute - can great title. Just a bit too much fill flash I think.  6 from me.</td>', 'Cute - can great title. Just a bit too much fill flash I think.  6 from me.', '2007-09-02 10:18:15.000000', NULL, 1),
(4049767, 576357, 34041, '<td valign="top">great artisic shot.  Could be in a gallary, but I don''t get the fit to the challenge.  7 from me still, for a beautiful shot, and giving you the benefit of the doubt about meeting the challenge</td>', 'great artisic shot.  Could be in a gallary, but I don''t get the fit to the challenge.  7 from me still, for a beautiful shot, and giving you the benefit of the doubt about meeting the challenge', '2007-09-02 10:19:47.000000', NULL, 1),
(4049771, 576365, 34041, '<td valign="top">Ha - get Out of the Box thinking. Just wish the DOF also included the plug.  It being so blurry, and so bright draws the eye and makes the whole image look OOF.  6 anyway for creative thinking, and nice reflections</td>', 'Ha - get Out of the Box thinking. Just wish the DOF also included the plug.  It being so blurry, and so bright draws the eye and makes the whole image look OOF.  6 anyway for creative thinking, and nice reflections', '2007-09-02 10:21:04.000000', NULL, 1),
(4049774, 578248, 34041, '<td valign="top">Tough fit for the challenge, but a great model shot. 6 for that.</td>', 'Tough fit for the challenge, but a great model shot. 6 for that.', '2007-09-02 10:23:49.000000', NULL, 1),
