(4050021, 577960, 39825, '<td valign="top">haha! VERY funny idea! the best in this challenge! 10 points for that! though you should perhaps have cropped away the left corner, but still such a cool picture! hope it wins!</td>', 'haha! VERY funny idea! the best in this challenge! 10 points for that! though you should perhaps have cropped away the left corner, but still such a cool picture! hope it wins!', '2007-09-02 12:27:52.000000', NULL, 1),
(4050050, 578281, 3214, '<td valign="top">good one!  great title.</td>', 'good one!  great title.', '2007-09-02 12:40:26.000000', NULL, 1),
(4050059, 578341, 3214, '<td valign="top">Good one!  Higher score if the photo screamed height by shooting from the base of the mast or something, now I have to interpolate that they are really high.</td>', 'Good one!  Higher score if the photo screamed height by shooting from the base of the mast or something, now I have to interpolate that they are really high.', '2007-09-02 12:42:27.000000', NULL, 1),
(4050066, 576320, 3214, '<td valign="top">Needs some context IMO to show why it''s risky, is he up high?  Can''t tell, could be on the 2nd floor. Interesting framing.</td>', 'Needs some context IMO to show why it''s risky, is he up high?  Can''t tell, could be on the 2nd floor. Interesting framing.', '2007-09-02 12:45:57.000000', NULL, 1),
(4050071, 577155, 3214, '<td valign="top">I like the two other kids, clouds, sense of height, the kid''s pose who has "lost it", but the garish tone of the partial desat dosn''t work for me. Not hurting your score from me though.</td>', 'I like the two other kids, clouds, sense of height, the kid''s pose who has "lost it", but the garish tone of the partial desat dosn''t work for me. Not hurting your score from me though.', '2007-09-02 12:48:02.000000', NULL, 1),
