(4050078, 578498, 3214, '<td valign="top">One of the best-conveyed sense of height in the challenge.</td>', 'One of the best-conveyed sense of height in the challenge.', '2007-09-02 12:49:24.000000', NULL, 1),
(4050145, 578641, 3214, '<td valign="top">Spot-on for the challenge, probably makes all of us think is that guy nuts?!  Great job conveying height.  Must be some expensive real estate!</td>', 'Spot-on for the challenge, probably makes all of us think is that guy nuts?!  Great job conveying height.  Must be some expensive real estate!', '2007-09-02 13:21:10.000000', NULL, 1),
(4050153, 578248, 3214, '<td valign="top">Without the title, this wouldn''t fit the challenge.  With the title there''s immediate identification with the model, as a female!  :-)  Well shot, too.</td>', 'Without the title, this wouldn''t fit the challenge.  With the title there''s immediate identification with the model, as a female!  :-)  Well shot, too.', '2007-09-02 13:23:59.000000', NULL, 1),
(4050160, 578124, 3214, '<td valign="top">Man, too bad about that dumpster, etc., in Basic.  Your subject looks a little older than most pursuing this sport, which adds to its applicability to the challenge!  Pretty old to be working without a net. Very skillful.</td>', 'Man, too bad about that dumpster, etc., in Basic.  Your subject looks a little older than most pursuing this sport, which adds to its applicability to the challenge!  Pretty old to be working without a net. Very skillful.', '2007-09-02 13:25:38.000000', NULL, 1),
(4050821, 577339, 35274, '<td valign="top">I love this image because it really expresses something strong. It''s hard to tell whether she is crying or laughing and I think that really adds to it. I think the greenish tint also really works well.</td>', 'I love this image because it really expresses something strong. It''s hard to tell whether she is crying or laughing and I think that really adds to it. I think the greenish tint also really works well.', '2007-09-02 18:12:28.000000', NULL, 1),
(4050822, 577943, 35274, '<td valign="top">Not really sure how exactly this fits the challenge, but I do rather like it. Wonderful tones and colors.</td>', 'Not really sure how exactly this fits the challenge, but I do rather like it. Wonderful tones and colors.', '2007-09-02 18:14:41.000000', NULL, 1),
